import re

from moler.exceptions import ParsingDone

from ta_moler.cmd.emssim.genericemssim import GenericEMSSIMCommand


class ParseSdl(GenericEMSSIMCommand):
    """Parsesdl command class."""

    def __init__(self, connection, filepath=None, prompt=None, newline_chars=None, runner=None):
        """
        Parsesdl command.

        :param connection: moler connection to device, terminal when command is executed.
        :param filepath: path to the file
        :param prompt: expected prompt sending by device after command execution
        :param newline_chars: Characters to split lines
        :param runner: Runner to run command
        """
        super(ParseSdl, self).__init__(connection=connection, prompt=prompt, newline_chars=newline_chars, runner=runner)

        self.filepath = filepath
        self.current_record = None

    def build_command_string(self):
        """
        Build command string from parameters passed to object.

        :return: String representation of command to send over connection to device.
        """
        cmd = "parse_sdl"
        if self.filepath:
            cmd = f"{cmd} {self.filepath}"
        return cmd

    def on_new_line(self, line, is_full_line):
        """
        Put your parsing code here.

        :param line: Line to process, can be only part of line. New line chars are removed from line.
        :param is_full_line: True if line had new line chars, False otherwise
        :return: None
        """
        if is_full_line:
            try:
                self._parse_line_record_name(line)
                self._parse_line_record_line(line)
            except ParsingDone:
                pass
        return super(ParseSdl, self).on_new_line(line, is_full_line)

    _re_record_name = re.compile(r"SDL_RECORD:\s(?P<RECORD_NAME>.+)", re.I)

    def _parse_line_record_name(self, line):
        if self._regex_helper.search_compiled(ParseSdl._re_record_name, line):
            self.current_record = self._regex_helper.group("RECORD_NAME")
            self.current_ret[self.current_record] = {}
            raise ParsingDone

    _re_record_line = re.compile(r"(?P<NUMBER>\d+)\s(?P<NAME>\S+)\s+(?P<VALUE>.+)\s\((?P<HEX_VALUE>.+)\)", re.I)

    def _parse_line_record_line(self, line):
        if self._regex_helper.search_compiled(ParseSdl._re_record_line, line):
            number = self._regex_helper.group("NUMBER")
            name = self._regex_helper.group("NAME")
            value = self._regex_helper.group("VALUE")
            hex_value = self._regex_helper.group("HEX_VALUE")
            self.current_ret[self.current_record].update({name: {"NUMBER": number, "VALUE": value, "HEX_VALUE": hex_value}})
            raise ParsingDone


